'use strict';

// MODULES //

import isnanf from '@stdlib/math-base-assert-is-nanf';
import isInfinitef from '@stdlib/math-base-assert-is-infinitef';
import expf from '@stdlib/math-base-special-expf';
import f32 from '@stdlib/number-float64-base-to-float32';
import PINF from '@stdlib/constants-float32-pinf';
import NINF from '@stdlib/constants-float32-ninf';
import MAXLOGF from '@stdlib/constants-float32-max-ln';
import polyvalP from './polyval_p.js';


// VARIABLES //

var ZERO = f32( 0.0 );
var ONE_HALF = f32( 0.5 );
var ONE = f32( 1.0 );


// MAIN //

/**
* Computes the hyperbolic sine of a single-precision floating-point number.
*
* ## Method
*
* The range is partitioned into two segments. If |x| <= 1, a polynomial approximation is used. Otherwise, the calculation is
*
* ```tex
* \operatorname{sinhf}(x) = \frac{ \exp(x) - \exp(-x) }{2}
* ```
*
* ## Notes
*
* -   Relative error:
*
*     | arithmetic | domain    | # trials | peak    | rms     |
*     |:----------:|:---------:|:--------:|:-------:|:-------:|
*     | IEEE       | +-MAXLOGF | 100000   | 1.1e-7  | 2.9e-8  |
*
* @param {number} x - input value
* @returns {number} hyperbolic sine
*
* @example
* var v = sinhf( 0.0 );
* // returns 0.0
*
* @example
* var v = sinhf( 2.0 );
* // returns ~3.627
*
* @example
* var v = sinhf( -2.0 );
* // returns ~-3.627
*
* @example
* var v = sinhf( NaN );
* // returns NaN
*/
function sinhf( x ) {
	var z;
	var a;

	x = f32( x );
	if ( x === ZERO ) {
		return x; // preserves signed zero
	}
	if ( isnanf( x ) ) {
		return x;
	}
	if ( isInfinitef( x ) ) {
		return x;
	}
	if ( x > ZERO ) {
		a = x;
	} else {
		a = -x;
	}
	// Handle overflow:
	if ( a > MAXLOGF ) {
		if ( x > ZERO ) {
			return PINF;
		}
		return NINF;
	}
	if ( a > ONE ) {
		z = expf( a );
		z = f32( f32( ONE_HALF * z ) - f32( ONE_HALF / z ) );
		if ( x < ZERO ) {
			z = -z;
		}
	} else {
		z = f32( x * x );
		z = f32( f32( f32( polyvalP( z ) * z ) * x ) + x );
	}
	return z;
}


// EXPORTS //

export default sinhf;
